with recursive cible as (select id from noeuds where version_id = '01a204be-5247-7d74-ac28-2ebd19c298b1'::uuid and code = 'comp:communication'), cone (id) as (                                      select id from cible where 'calcul' = 'calcul'   union   select e.source_id from cone join entrees e on e.noeud_id = cone.id ), sous_arbre (placement_id, noeud_id) as (            select p.id, p.noeud_id from placements p join cible on p.noeud_id = cible.id where 'calcul' = 'placement'   union   select c.id, c.noeud_id from sous_arbre s join placements c on c.parent_id = s.placement_id ), feuilles as (   select n.id, n.code from noeuds n   where n.type = 'donnees' and n.bareme_id is not null     and n.id in (select id from cone union select noeud_id from sous_arbre) ), membres as (select p.id from participants p where p.groupe_id = '019e807a-ec0b-7c29-8b12-e3d17f3e0469'::uuid), ne as (select ne.participant_id, ne.noeud_id from non_evaluations ne        where ne.version_id = '01a204be-5247-7d74-ac28-2ebd19c298b1'::uuid and ne.active and ne.participant_id in (select id from membres)), couvre (participant_id, placement_id, noeud_id) as (      select ne.participant_id, p.id, ne.noeud_id from ne left join placements p on p.noeud_id = ne.noeud_id   union   select c.participant_id, enf.id, enf.noeud_id from couvre c join placements enf on enf.parent_id = c.placement_id ) select m.id as participant_id, f.code as noeud,        exists (select 1 from couvre cv where cv.participant_id = m.id and cv.noeud_id = f.id) as couvert,        (select count(*) from feuilles)::int as nb_feuilles from membres m cross join feuilles f where not exists (select 1 from cases c where c.version_id = '01a204be-5247-7d74-ac28-2ebd19c298b1'::uuid and c.participant_id = m.id and c.noeud_id = f.id and c.valeur is not null) order by 1, 2; ;
